import {beforeAll,afterAll,beforeEach,describe,it,expect} from 'vitest';import {Miniflare,convertV4MiniflareOptions} from 'miniflare';import {readFileSync,readdirSync} from 'node:fs';import {mcpVersion,validateRpc,validateRedirect} from '../src/mcp';import {digest} from '../src/security';
let mf:Miniflare,db:D1Database;const origin='http://localhost:8787';let cookie:string,csrf:string,user:string,pid:string,pid2:string;const meta={'io.modelcontextprotocol/protocolVersion':mcpVersion,'io.modelcontextprotocol/clientCapabilities':{},'io.modelcontextprotocol/clientInfo':{name:'untrusted-test-client',version:'1'}};
async function api(path:string,method='GET',body?:unknown){if(method==='POST'&&/\/proposals\/[^/]+\/(approve|reject)$/.test(path)&&body&&typeof body==='object'){const r:any=await (await api(path.replace(/\/(approve|reject)$/,'/review'))).json();body={...body,reviewDigest:r.reviewDigest,baseRevision:r.baseRevision,acceptRisk:r.risk,approveDestructive:true};}return mf.dispatchFetch(origin+path,{method,headers:{origin,cookie,'x-csrf-token':csrf,'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})})}
async function rpc(method:string,params:Record<string,unknown>={},token?:string,project=pid,extra:Record<string,string>={}){return mf.dispatchFetch(origin+'/mcp/projects/'+project,{method:'POST',headers:{'content-type':'application/json',accept:'application/json, text/event-stream','MCP-Protocol-Version':mcpVersion,'Mcp-Method':method,...typeof params.name==='string'?{'Mcp-Name':params.name}:{},...token?{authorization:'Bearer '+token}:{},...extra},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params:{...params,_meta:meta}})})}
async function form(path:string,data:Record<string,string>){return mf.dispatchFetch(origin+path,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data).toString()})}
const verifier='a'.repeat(43);let client:string;async function grant(selected=['project.read']){const challenge=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const q=new URLSearchParams({response_type:'code',client_id:client,redirect_uri:'https://client.example/callback',code_challenge:challenge,code_challenge_method:'S256',state:'test-state',resource:origin+'/mcp/projects/'+pid,scope:selected.join(' ')});const authorize=await mf.dispatchFetch(origin+'/oauth/authorize?'+q,{headers:{cookie},redirect:'manual'});expect(authorize.status).toBe(303);const consent=new URL(authorize.headers.get('location')!).hash.split('consent=')[1]!;const approval=await api('/api/projects/'+pid+'/mcp/consents/'+consent+'/approve','POST',{clientId:client,resource:origin+'/mcp/projects/'+pid,scopes:selected,redirectUri:'https://client.example/callback'});expect(approval.status).toBe(200);const callback=new URL((await approval.json() as any).redirect);expect(callback.searchParams.get('iss')).toBe(origin);const data={grant_type:'authorization_code',client_id:client,redirect_uri:'https://client.example/callback',resource:origin+'/mcp/projects/'+pid,code_verifier:verifier,code:callback.searchParams.get('code')!};return {data,consent}}
async function token(selected=['project.read']){const g=await grant(selected);const r=await form('/oauth/token',g.data);expect(r.status).toBe(200);return (await r.json() as any).access_token as string}
beforeAll(async()=>{mf=new Miniflare(convertV4MiniflareOptions({workers:[{name:'control',modules:true,scriptPath:'dist/index.js',compatibilityDate:'2026-10-08',d1Databases:['DB'],bindings:{APP_ORIGIN:origin,REGISTRATION_ENABLED:'true',RUNTIME_ENABLED:'false'}}]}));db=await mf.getD1Database('DB');for(const file of readdirSync('migrations').filter(x=>x.endsWith('.sql')).sort()){for(const sql of readFileSync('migrations/'+file,'utf8').replace(/^--.*$/gm,'').split(/;\n(?=(?:CREATE|PRAGMA|$))/).map(x=>x.trim()).filter(Boolean))await db.prepare(sql).run()}const r=await api('/api/auth/register','POST',{email:'mcp-owner@example.test',password:'secure-password-long-1234'});cookie=r.headers.get('set-cookie')!.split(';')[0]!;const a:any=await r.json();csrf=a.csrfToken;user=a.userId;const ws:any=await (await api('/api/workspaces','POST',{name:'MCP QA'})).json();pid=(await (await api('/api/workspaces/'+ws.id+'/projects','POST',{name:'MCP project'})).json() as any).id;pid2=(await (await api('/api/workspaces/'+ws.id+'/projects','POST',{name:'Other project'})).json() as any).id;const q:any=await (await api('/api/projects/'+pid+'/proposals','POST',{baseRevision:0,bundle:{stack:'static-web-v1',files:{'index.html':'<h1>original</h1>','keep.txt':'unchanged','app.js':'const x=1;','sensitive.txt':'sk-abcdefghijklmnopqrstuvwx'},schema:[],permissions:[]}})).json();await api('/api/proposals/'+q.id+'/approve','POST',{digest:q.digest});},30000);beforeEach(async()=>{await db.prepare('DELETE FROM rate_limits').run();await db.prepare('DELETE FROM usage_counters').run();await db.prepare('DELETE FROM abuse_cooldowns').run();client=(await (await api('/api/projects/'+pid+'/mcp/clients','POST',{name:'QA client',redirectUri:'https://client.example/callback'})).json() as any).id});afterAll(async()=>mf?.dispose());
describe('Part 14 MCP current 2026-07-28 authorization and stateless tools',()=>{
 it('public discovery includes resultType, supported version and no protected data',async()=>{const r:any=await (await rpc('server/discover')).json();expect(r.result.resultType).toBe('complete');expect(r.result.supportedVersions).toEqual([mcpVersion]);const list:any=await (await rpc('tools/list')).json();expect(list.result.tools.map((x:any)=>x.name)).toEqual(['velnavoq.capabilities']);expect((await rpc('tools/call',{name:'velnavoq.project',arguments:{}})).status).toBe(401)});
 it('validates version/header/name mirror and invalid Origin without cookie authority',async()=>{for(const extra of [{'Mcp-Method':'ping'},{'Mcp-Name':'velnavoq.files'},{'MCP-Protocol-Version':'2025-11-25'}]){const r=await rpc('tools/call',{name:'velnavoq.project',arguments:{}},undefined,pid,extra);expect(r.status).toBe(400);expect((await r.json() as any).error.code).toBe(-32020)}expect((await rpc('tools/list',{},undefined,pid,{origin:'https://evil.example'})).status).toBe(403);const r=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'GET'});expect(r.status).toBe(405)});
 it('requires exact consent before code issuance; registration alone grants nothing',async()=>{expect((await rpc('tools/call',{name:'velnavoq.project',arguments:{}},'f'.repeat(64))).status).toBe(401);expect((await form('/oauth/token',{grant_type:'authorization_code',code:'invented',code_verifier:verifier})).status).toBe(400);const listing:any=await (await api('/api/projects/'+pid+'/mcp')).json();expect(listing.tokens).toHaveLength(0)});
 it('S256 binds code to client, exact redirect, resource and verifier; code single use',async()=>{const g=await grant();for(const change of [{code_verifier:'b'.repeat(43)},{client_id:'wrong'},{redirect_uri:'https://evil.example'},{resource:origin+'/mcp/projects/'+pid2}])expect((await form('/oauth/token',{...g.data,...change})).status).toBe(400);expect((await form('/oauth/token',g.data)).status).toBe(200);expect((await form('/oauth/token',g.data)).status).toBe(400)});
 it('scope-limited tool discovery and invocation, no token passthrough or cross-project access',async()=>{const t=await token();const r:any=await (await rpc('tools/list',{},t)).json();expect(r.result.tools.map((x:any)=>x.name)).toEqual(['velnavoq.capabilities','velnavoq.project']);expect((await rpc('tools/call',{name:'velnavoq.files',arguments:{path:'app.js'}},t)).status).toBe(403);expect((await rpc('tools/call',{name:'velnavoq.project'},t,pid2)).status).toBe(401);expect((await rpc('tools/list',{},'not-an-issued-token')).status).toBe(401);const project:any=await (await rpc('tools/call',{name:'velnavoq.project'},t)).json();expect(project.result.structuredContent.data.name).toBe('MCP project');expect(project.result._meta['app.velnavoq/trust']).toBe('untrusted-data-no-authority')});
 it('refuses secret-bearing file and traversal, returns exact inert untrusted source',async()=>{const t=await token(['files.read']);const r:any=await (await rpc('tools/call',{name:'velnavoq.files',arguments:{path:'app.js'}},t)).json();expect(r.result.structuredContent.data.content).toBe('const x=1;');for(const path of ['../app.js','sensitive.txt']){const denied:any=await (await rpc('tools/call',{name:'velnavoq.files',arguments:{path}},t)).json();expect(denied.result.isError).toBe(true)}expect((await rpc('tools/call',{name:'velnavoq.files',arguments:{path:'app.js',command:'rm -rf /'}},t)).status).toBe(400)});
 it('protected mutation only creates immutable reviewable proposal; cannot apply',async()=>{const t=await token(['patch.propose']);const projectToken=await token(['project.read']);const c:any={snapshot:(await (await rpc('tools/call',{name:'velnavoq.project'},projectToken)).json() as any).result.structuredContent.data};const r:any=await (await rpc('tools/call',{name:'velnavoq.propose_patch',arguments:{baseRevision:c.snapshot.revision,sourceDigest:c.snapshot.sourceDigest,changes:[{path:'app.js',operation:'MODIFY',previousDigest:await digest('const x=1;'),content:'const x=2;',to:null,reason:'User-reviewed proposed change',risk:'low'}]}},t)).json();expect(r.result.isError).toBe(false);expect(r.result.structuredContent.data.applied).toBe(false);const stored:any=await db.prepare('SELECT status FROM proposals WHERE id=?').bind(r.result.structuredContent.data.id).first();expect(stored.status).toBe('pending');expect((await db.prepare('SELECT revision FROM projects WHERE id=?').bind(pid).first<any>())!.revision).toBe(1);expect((await rpc('tools/call',{name:'velnavoq.apply',arguments:{}},t)).status).toBe(400)});
 it('token revocation, expiry, client revocation and membership removal immediately deny access',async()=>{const t=await token();const row:any=await db.prepare('SELECT id FROM mcp_access_tokens WHERE token_hash=?').bind(await digest(t)).first();expect((await api('/api/projects/'+pid+'/mcp/tokens/'+row.id+'/revoke','POST',{})).status).toBe(200);expect((await rpc('tools/list',{},t)).status).toBe(401);await expect(db.prepare('UPDATE mcp_access_tokens SET revoked_at=NULL WHERE id=?').bind(row.id).run()).rejects.toThrow();const t2=await token();await api('/api/projects/'+pid+'/mcp/clients/'+client+'/revoke','POST',{});expect((await rpc('tools/list',{},t2)).status).toBe(401)});
 it('metadata advertises exact issuer/resource with no dynamic registration or token passthrough',async()=>{const a:any=await (await api('/.well-known/oauth-authorization-server')).json();expect(a.issuer).toBe(origin+'/oauth/account');expect(a.code_challenge_methods_supported).toEqual(['S256']);expect(a.registration_endpoint).toBe(origin+'/oauth/account/register');const r:any=await (await api('/.well-known/oauth-protected-resource/mcp/projects/'+pid)).json();expect(r.resource).toBe(origin+'/mcp/projects/'+pid);const denied=await rpc('tools/call',{name:'velnavoq.project'});expect(denied.headers.get('www-authenticate')).toContain('resource_metadata=')});
 it('rate limits repeated requests and audits without raw tokens/source',async()=>{const t=await token();let last:Response|undefined;for(let i=0;i<31;i++)last=await rpc('tools/list',{},t);expect(last!.status).toBe(429);const logs:any[]=(await db.prepare('SELECT * FROM mcp_audit').all()).results;expect(logs.some(x=>x.outcome==='rate_limited')).toBe(true);expect(JSON.stringify(logs)).not.toContain(t);expect(JSON.stringify(logs)).not.toContain('const x=1')});
 it.each(['http://evil.example/callback','https://user:password@example.test/','https://client.example/#code','javascript:alert(1)'])('rejects unsafe redirect %s',s=>expect(()=>validateRedirect(s)).toThrow());
 it('allows exact HTTPS or loopback redirects, rejects missing metadata and accepts safe encoded tool-name mirror',()=>{expect(validateRedirect('http://127.0.0.1:3000/callback')).toContain('127.0.0.1');const req=new Request(origin,{headers:{'MCP-Protocol-Version':mcpVersion,'Mcp-Method':'tools/call','Mcp-Name':'=?base64?'+btoa('velnavoq.project')+'?='}});expect(()=>validateRpc(req,{jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'velnavoq.project',_meta:meta}})).not.toThrow();expect(()=>validateRpc(req,{jsonrpc:'2.0',id:1,method:'tools/call',params:{}})).toThrow()});
});

describe('Part 14 misuse, revocation and isolation boundaries',()=>{
 it('expired token and forged audience/issuer cannot be used',async()=>{const t=await token();const row:any=await db.prepare('SELECT * FROM mcp_access_tokens WHERE token_hash=?').bind(await digest(t)).first();for(const [value,audience,iss,expires] of [['e'.repeat(64),row.audience,origin,Date.now()-1],['d'.repeat(64),origin+'/mcp/projects/'+pid2,origin,Date.now()+10000],['c'.repeat(64),row.audience,'https://evil.example',Date.now()+10000]] as const){await db.prepare('INSERT INTO mcp_access_tokens(id,token_hash,client_id,project_id,user_id,issuer,audience,scopes,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),await digest(value),row.client_id,pid,user,iss,audience,row.scopes,expires,Date.now()).run();expect((await rpc('tools/list',{},value)).status).toBe(401)}});
 it('membership downgrade revokes effective grants even without token deletion',async()=>{const t=await token();const p:any=await db.prepare('SELECT workspace_id FROM projects WHERE id=?').bind(pid).first();await db.prepare("INSERT INTO users(id,email,password_hash,password_salt,created_at) VALUES('mcp-other-owner','other-owner@example.test','x','y',1)").run();await db.prepare("INSERT INTO memberships(workspace_id,user_id,role) VALUES(?,'mcp-other-owner','owner')").bind(p.workspace_id).run();await db.prepare("UPDATE memberships SET role='editor' WHERE user_id=? AND workspace_id=?").bind(user,p.workspace_id).run();expect((await rpc('tools/list',{},t)).status).toBe(401);expect((await api('/api/projects/'+pid+'/mcp')).status).toBe(404);await db.prepare("UPDATE memberships SET role='owner' WHERE user_id=? AND workspace_id=?").bind(user,p.workspace_id).run()});
 it('session cookie is not an MCP bearer token and token cannot replace CSRF approval',async()=>{const r=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'POST',headers:{cookie,'content-type':'application/json',accept:'application/json,text/event-stream','Mcp-Method':'tools/call','Mcp-Name':'velnavoq.project','MCP-Protocol-Version':mcpVersion},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'velnavoq.project',_meta:meta}})});expect(r.status).toBe(401);const t=await token();const denied=await mf.dispatchFetch(origin+'/api/projects/'+pid+'/mcp/clients',{method:'POST',headers:{authorization:'Bearer '+t,origin,'content-type':'application/json'},body:JSON.stringify({name:'cannot',redirectUri:'https://client.example'})});expect(denied.status).toBe(401)});
 it('OAuth revoke immediately invalidates token and never discloses whether unknown token existed',async()=>{const t=await token();expect((await form('/oauth/revoke',{token:t,client_id:client})).status).toBe(200);expect((await rpc('tools/list',{},t)).status).toBe(401);expect((await form('/oauth/revoke',{token:'unknown',client_id:client})).status).toBe(200)});
 it('parallel code redemption issues at most one token',async()=>{const g=await grant();const results=await Promise.all([form('/oauth/token',g.data),form('/oauth/token',g.data)]);expect(results.map(x=>x.status).sort()).toEqual([200,400])});
 it('authorization rejects arbitrary callbacks, plain PKCE, wrong resource and duplicate parameters',async()=>{const base=new URLSearchParams({client_id:client,redirect_uri:'https://client.example/callback',response_type:'code',state:'state',code_challenge:'a'.repeat(43),code_challenge_method:'S256',resource:origin+'/mcp/projects/'+pid,scope:'project.read'});for(const fields of [{redirect_uri:'https://evil.example'},{code_challenge_method:'plain'},{resource:origin+'/mcp/projects/'+pid2}]){const q=new URLSearchParams(base);for(const [k,v] of Object.entries(fields))q.set(k,v);expect((await mf.dispatchFetch(origin+'/oauth/authorize?'+q,{headers:{cookie},redirect:'manual'})).status).toBe(400)}base.append('client_id','different');expect((await mf.dispatchFetch(origin+'/oauth/authorize?'+base,{headers:{cookie},redirect:'manual'})).status).toBe(400)});
 it('unknown notifications and legacy initialization never gain session authority',async()=>{const body={jsonrpc:'2.0',method:'notifications/initialized',params:{_meta:meta}};const r=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'POST',headers:{accept:'application/json,text/event-stream','content-type':'application/json','MCP-Protocol-Version':mcpVersion,'Mcp-Method':body.method},body:JSON.stringify(body)});expect(r.status).toBe(404);expect((await rpc('initialize')).status).toBe(400);expect((await rpc('tools/list',{},undefined,pid,{'Mcp-Session-Id':'forged'})).status).toBe(400)});
});

describe('MCP bounded outcomes',()=>{
 it('version negotiation reports requested and supported; denial is audited',async()=>{const newer={...meta,'io.modelcontextprotocol/protocolVersion':'2099-01-01'};const r=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'POST',headers:{accept:'application/json,text/event-stream','content-type':'application/json','MCP-Protocol-Version':'2099-01-01','Mcp-Method':'ping'},body:JSON.stringify({jsonrpc:'2.0',id:7,method:'ping',params:{_meta:newer}})});expect(r.status).toBe(400);expect((await r.json() as any).error.data).toEqual({requested:'2099-01-01',supported:[mcpVersion,'2025-03-26','2025-06-18','2025-11-25']});expect((await db.prepare("SELECT COUNT(*) AS n FROM mcp_audit WHERE outcome='mcp_unsupported_version'").first<any>())!.n).toBeGreaterThan(0)});
 it('oversized patch result is refused before proposal writes',async()=>{const t=await token(['patch.propose']);const c:any=await (await api('/api/projects/'+pid+'/agent/context')).json();const before=(await db.prepare('SELECT COUNT(*) AS n FROM proposals WHERE project_id=?').bind(pid).first<any>())!.n;const r:any=await (await rpc('tools/call',{name:'velnavoq.propose_patch',arguments:{baseRevision:c.snapshot.revision,sourceDigest:c.snapshot.sourceDigest,changes:['one.txt','two.txt'].map(path=>({path,operation:'CREATE',previousDigest:null,content:'a'.repeat(78000),to:null,reason:'Bounded output test',risk:'low'}))}},t)).json();expect(r.result.isError).toBe(true);expect(r.result.content[0].text).toBe('mcp_result_too_large');expect((await db.prepare('SELECT COUNT(*) AS n FROM proposals WHERE project_id=?').bind(pid).first<any>())!.n).toBe(before)});
});

it('bad schema argument types are protocol errors, not tool execution failures',async()=>{const t=await token(['files.read','patch.propose']);for(const [name,args] of [['velnavoq.files',{path:5}],['velnavoq.propose_patch',{baseRevision:'one',sourceDigest:'abc',changes:[]}]] as const){const r=await rpc('tools/call',{name,arguments:args},t);expect(r.status).toBe(400);expect((await r.json() as any).error.code).toBe(-32602)}});

describe('ASVS OAuth remediation',()=>{
 it('valid reused code revokes its issued token; wrong verifier cannot cause revocation',async()=>{const g=await grant();const issued=await form('/oauth/token',g.data);expect(issued.status).toBe(200);const t=(await issued.json() as any).access_token;expect((await rpc('tools/list',{},t)).status).toBe(200);expect((await form('/oauth/token',{...g.data,code_verifier:'b'.repeat(43)})).status).toBe(400);expect((await rpc('tools/list',{},t)).status).toBe(200);expect((await form('/oauth/token',g.data)).status).toBe(400);expect((await rpc('tools/list',{},t)).status).toBe(401)});
 it('token issuance failure rolls back code consumption and lineage',async()=>{const g=await grant();await db.prepare("CREATE TRIGGER test_code_lineage_fail BEFORE INSERT ON oauth_code_tokens BEGIN SELECT RAISE(ABORT,'test_lineage_fail'); END").run();expect((await form('/oauth/token',g.data)).status).toBe(400);expect((await db.prepare('SELECT consumed_at FROM mcp_consents WHERE id=?').bind(g.consent).first<any>()).consumed_at).toBeNull();expect(await db.prepare('SELECT 1 FROM mcp_access_tokens WHERE client_id=?').bind(client).first()).toBeNull();await db.prepare('DROP TRIGGER test_code_lineage_fail').run();expect((await form('/oauth/token',g.data)).status).toBe(200)});
 it('simultaneous code requests never produce two live issued tokens',async()=>{const g=await grant();const r=await Promise.all([form('/oauth/token',g.data),form('/oauth/token',g.data)]);expect(r.filter(x=>x.status===200).length).toBeLessThanOrEqual(1);expect((await db.prepare('SELECT count(*) AS n FROM mcp_access_tokens WHERE client_id=? AND revoked_at IS NULL').bind(client).first<any>()).n).toBe(0)});


});

describe('Part 30 source automation with exact owner grant',()=>{
 it('runs checks and lists files with separate scopes',async()=>{const t=await token(['files.read','checks.run','project.read']);const listed:any=await (await rpc('tools/call',{name:'velnavoq.list_files',arguments:{}},t)).json();expect(listed.result.structuredContent.data.files.some((x:any)=>x.path==='app.js')).toBe(true);const s:any=(await (await rpc('tools/call',{name:'velnavoq.project'},t)).json() as any).result.structuredContent.data;const check:any=await (await rpc('tools/call',{name:'velnavoq.run_checks',arguments:{baseRevision:s.revision,sourceDigest:s.sourceDigest}},t)).json();expect(check.result.structuredContent.data.executedCode).toBe(false);expect(check.result.structuredContent.data.passed).toBe(false);expect(check.result.structuredContent.data.diagnostic).toBe('deployment_secret_denied')});
 it('refuses apply without owner sandbox consent, permits source-only apply then revocation denies',async()=>{const t=await token(['sandbox.write','project.read']);const s:any=(await (await rpc('tools/call',{name:'velnavoq.project'},t)).json() as any).result.structuredContent.data;const text:any=await db.prepare('SELECT content FROM file_versions WHERE project_id=? AND version=? AND path=?').bind(pid,s.revision,'app.js').first();const changes=[{path:'app.js',operation:'MODIFY',previousDigest:await digest(text.content),content:'const changed=30;',to:null,reason:'Requested sandbox edit',risk:'low'}];const call=()=>rpc('tools/call',{name:'velnavoq.apply_patch',arguments:{baseRevision:s.revision,sourceDigest:s.sourceDigest,changes}},t);expect((await (await call()).json() as any).result.content[0].text).toBe('sandbox_owner_grant_required');const manage=await mf.dispatchFetch(origin+'/api/projects/'+pid+'/mcp/sandbox/'+client,{method:'PUT',headers:{origin,cookie,'x-csrf-token':csrf,'content-type':'application/json'},body:JSON.stringify({enabled:true,acknowledge:'source-only-no-publish',allowDelete:false,hours:1,maxChanges:50})});expect(manage.status).toBe(200);const applied:any=await (await call()).json();expect(applied.result.isError).toBe(false);expect(applied.result.structuredContent.data.published).toBe(false);expect((await db.prepare('SELECT revision FROM projects WHERE id=?').bind(pid).first<any>()).revision).toBe(s.revision+1);expect((await (await call()).json() as any).result.content[0].text).toBe('stale_mcp_snapshot');await db.prepare('UPDATE mcp_sandbox_grants SET revoked_at=? WHERE client_id=?').bind(Date.now(),client).run();const fresh:any=(await (await rpc('tools/call',{name:'velnavoq.project'},t)).json() as any).result.structuredContent.data;const denied:any=await (await rpc('tools/call',{name:'velnavoq.apply_patch',arguments:{baseRevision:fresh.revision,sourceDigest:fresh.sourceDigest,changes:[{...changes[0],previousDigest:await digest('const changed=30;'),content:'const changed=31;'}]}},t)).json();expect(denied.result.content[0].text).toBe('sandbox_owner_grant_required')});
 it('legacy initialize and initialized work with Streamable HTTP JSON',async()=>{const response=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'POST',headers:{'content-type':'application/json',accept:'application/json, text/event-stream'},body:JSON.stringify({jsonrpc:'2.0',id:100,method:'initialize',params:{protocolVersion:'2025-11-25',capabilities:{},clientInfo:{name:'qa',version:'1'}}})});const data:any=await response.json();expect(data.result.protocolVersion).toBe('2025-11-25');expect(data.result.serverInfo.name).toBe('velnavoq');expect(data.result.resultType).toBeUndefined();const initialized=await mf.dispatchFetch(origin+'/mcp/projects/'+pid,{method:'POST',headers:{'content-type':'application/json',accept:'application/json, text/event-stream','MCP-Protocol-Version':'2025-11-25'},body:JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'})});expect(initialized.status).toBe(202)});
});
it('Part31 project dynamic registration completes owner consent PKCE and project issuer, never registration authority',async()=>{const registration=await mf.dispatchFetch(origin+'/oauth/projects/'+pid+'/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({client_name:'External Grok QA',redirect_uris:['https://grok-client.example/callback'],token_endpoint_auth_method:'none'})});expect(registration.status).toBe(201);const c:any=await registration.json();expect(await db.prepare('SELECT id FROM mcp_clients WHERE id=?').bind(c.client_id).first()).toBeNull();const challenge=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const q=new URLSearchParams({response_type:'code',client_id:c.client_id,redirect_uri:'https://grok-client.example/callback',code_challenge:challenge,code_challenge_method:'S256',state:'external-state',resource:origin+'/mcp/projects/'+pid,scope:'project.read schema.read'});const authorize=await mf.dispatchFetch(origin+'/oauth/authorize?'+q,{headers:{cookie},redirect:'manual'});expect(authorize.status).toBe(303);const consent=new URL(authorize.headers.get('location')!).hash.split('consent=')[1]!;const approval:any=await (await api('/api/projects/'+pid+'/mcp/consents/'+consent+'/approve','POST',{clientId:c.client_id,resource:origin+'/mcp/projects/'+pid,scopes:['project.read','schema.read'],redirectUri:'https://grok-client.example/callback'})).json();const callback=new URL(approval.redirect);expect(callback.searchParams.get('iss')).toBe(origin+'/oauth/projects/'+pid);const token:any=await (await form('/oauth/token',{grant_type:'authorization_code',client_id:c.client_id,redirect_uri:'https://grok-client.example/callback',resource:origin+'/mcp/projects/'+pid,code_verifier:verifier,code:callback.searchParams.get('code')!})).json();expect(token.access_token).toBeTruthy();expect((await rpc('tools/list',{},token.access_token)).status).toBe(200);const row=await db.prepare('SELECT issuer FROM mcp_access_tokens WHERE client_id=?').bind(c.client_id).first<any>();expect(row.issuer).toBe(origin+'/oauth/projects/'+pid);expect((await rpc('tools/list',{},token.access_token,pid2)).status).toBe(401);});
async function accountGrant(projectIds:string[],workspaces:string[]=[],requested=['project.read','files.read'],requestApprovals=false){const registered:any=await (await mf.dispatchFetch(origin+'/oauth/account/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({client_name:'Account QA',redirect_uris:['https://account-client.example/callback'],token_endpoint_auth_method:'none'})})).json();const challenge=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const query=new URLSearchParams({client_id:registered.client_id,redirect_uri:'https://account-client.example/callback',resource:origin+'/mcp',response_type:'code',scope:requested.join(' '),state:'account-test',code_challenge:challenge,code_challenge_method:'S256'});const auth=await mf.dispatchFetch(origin+'/oauth/account/authorize?'+query,{headers:{cookie},redirect:'manual'});expect(auth.status).toBe(303);const consent=new URL(auth.headers.get('location')!).hash.split('accountConsent=')[1]!;const approval=await api('/api/account-mcp/consents/'+consent+'/approve','POST',{clientId:registered.client_id,redirectUri:'https://account-client.example/callback',resource:origin+'/mcp',scopes:requested,projectIds,createWorkspaceIds:workspaces,requestApprovals});if(approval.status!==200)return {approval};const callback=new URL((await approval.json() as any).redirect);expect(callback.searchParams.get('iss')).toBe(origin+'/oauth/account');const data={grant_type:'authorization_code',client_id:registered.client_id,redirect_uri:'https://account-client.example/callback',resource:origin+'/mcp',code:callback.searchParams.get('code')!,code_verifier:verifier};const response=await form('/oauth/account/token',data);expect(response.status).toBe(200);const token:any=await response.json();return {raw:token.access_token,data};}
async function accountRpc(name:string,args:any={},raw?:string,method='tools/call'){return mf.dispatchFetch(origin+'/mcp',{method:'POST',headers:{'content-type':'application/json',accept:'application/json, text/event-stream','MCP-Protocol-Version':'2025-11-25',...(raw?{authorization:'Bearer '+raw}:{})},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params:method==='tools/list'?{}:{name,arguments:args}})});}
it('account MCP defaults none; exact granted IDs/name only; cross project and user isolation',async()=>{const empty=await accountGrant([]);const list:any=await (await accountRpc('velnavoq.list_projects',{},empty.raw)).json();expect(JSON.parse(list.result.content[0].text).projects).toEqual([]);expect((await (await accountRpc('velnavoq.project',{projectId:pid},empty.raw)).json() as any).error).toBeTruthy();const selected=await accountGrant([pid]);const projects:any=await (await accountRpc('velnavoq.list_projects',{},selected.raw)).json();expect(JSON.parse(projects.result.content[0].text).projects.map((p:any)=>p.id)).toEqual([pid]);const read:any=await (await accountRpc('velnavoq.project',{projectName:'MCP project'},selected.raw)).json();expect(read.result.structuredContent.data.id).toBe(pid);expect((await (await accountRpc('velnavoq.project',{projectId:pid2},selected.raw)).json() as any).error).toBeTruthy();const row:any=await db.prepare('SELECT workspace_id FROM projects WHERE id=?').bind(pid).first();await db.prepare("UPDATE memberships SET role='editor' WHERE workspace_id=? AND user_id=?").bind(row.workspace_id,user).run();expect(JSON.parse((await (await accountRpc('velnavoq.list_projects',{},selected.raw)).json() as any).result.content[0].text).projects).toEqual([]);await db.prepare("UPDATE memberships SET role='owner' WHERE workspace_id=? AND user_id=?").bind(row.workspace_id,user).run();});
it('account name ambiguity refused and revocation cascades child tokens, code replay revokes connection',async()=>{await db.prepare('UPDATE projects SET name=? WHERE id=?').bind('MCP project',pid2).run();const g=await accountGrant([pid,pid2]);expect((await (await accountRpc('velnavoq.project',{projectName:'MCP project'},g.raw)).json() as any).error).toBeTruthy();expect((await accountRpc('velnavoq.project',{projectId:pid},g.raw)).status).toBe(200);expect((await form('/oauth/account/token',g.data!)).status).toBe(400);expect((await accountRpc('velnavoq.list_projects',{},g.raw)).status).toBe(401);const row:any=await db.prepare('SELECT revoked_at FROM mcp_access_tokens WHERE id IN(SELECT child_token_id FROM account_mcp_projects WHERE token_id=(SELECT id FROM account_mcp_tokens WHERE token_hash=?))').bind(await digest(g.raw)).first();expect(row.revoked_at).toBeTruthy();await db.prepare('UPDATE projects SET name=? WHERE id=?').bind('Other project',pid2).run();});
it('account create requires explicit owned workspace grant and does not enable Autopilot',async()=>{const ws:any=await db.prepare('SELECT workspace_id FROM projects WHERE id=?').bind(pid).first();const g=await accountGrant([], [ws.workspace_id],['project.read','projects.create']);expect((await (await accountRpc('velnavoq.create_project',{workspaceId:'not-granted',name:'Denied'},g.raw)).json() as any).error).toBeTruthy();const created:any=await (await accountRpc('velnavoq.create_project',{workspaceId:ws.workspace_id,name:'Account-created synthetic'},g.raw)).json();const data=JSON.parse(created.result.content[0].text);expect(data.id).toBeTruthy();expect(data.autopilot).toBe(false);expect(await db.prepare('SELECT client_id FROM mcp_sandbox_grants WHERE project_id=?').bind(data.id).first()).toBeNull();expect((await accountRpc('velnavoq.project',{projectId:data.id},g.raw)).status).toBe(200);expect((await accountRpc('velnavoq.list_projects')).status).toBe(401);});
it('account consent refuses another users project and cannot imply Autopilot from scopes',async()=>{const outsider=crypto.randomUUID(),ws=crypto.randomUUID(),foreign=crypto.randomUUID();await db.prepare('INSERT INTO users(id,email,password_hash,password_salt,created_at) SELECT ?,?,?,?,? FROM users LIMIT 1').bind(outsider,outsider+'@example.test','not-usable','not-usable',Date.now()).run();await db.prepare('INSERT INTO workspaces VALUES(?,?,?)').bind(ws,'Foreign',Date.now()).run();await db.prepare("INSERT INTO memberships VALUES(?,?,'owner')").bind(ws,outsider).run();await db.prepare('INSERT INTO projects(id,workspace_id,name,created_at,created_by) VALUES(?,?,?,?,?)').bind(foreign,ws,'Foreign',Date.now(),outsider).run();const denied=await accountGrant([foreign]);expect(denied.approval?.status).toBe(404);const g=await accountGrant([pid],[],['project.read','sandbox.write','checks.run']);const p:any=await (await accountRpc('velnavoq.project',{projectId:pid},g.raw)).json();const write:any=await (await accountRpc('velnavoq.apply_patch',{projectId:pid,baseRevision:p.result.structuredContent.data.revision,sourceDigest:p.result.structuredContent.data.sourceDigest,changes:[{path:'account-created.txt',operation:'CREATE',previousDigest:null,content:'synthetic',to:null,reason:'Test only',risk:'low'}]},g.raw)).json();expect(write.result.isError).toBe(true);expect(write.result.content[0].text).toBe('sandbox_owner_grant_required');});
it('Part33 one connector requests exact access and owner approves without reauthorization',async()=>{const g=await accountGrant([],[],['project.read','files.read','projects.create'],true);const targets:any=await (await accountRpc('velnavoq.list_access_targets',{},g.raw)).json();expect(JSON.parse(targets.result.content[0].text).projects.some((p:any)=>p.id===pid)).toBe(true);const args={projectId:pid,scopes:['project.read']};const req:any=JSON.parse((await (await accountRpc('velnavoq.request_project_access',args,g.raw)).json() as any).result.content[0].text);const repeat:any=JSON.parse((await (await accountRpc('velnavoq.request_project_access',args,g.raw)).json() as any).result.content[0].text);expect(repeat.requestId).toBe(req.requestId);expect((await (await accountRpc('velnavoq.project',{projectId:pid},g.raw)).json() as any).error).toBeTruthy();const listing:any=await (await api('/api/account-mcp')).json();const r=listing.requests.find((x:any)=>x.id===req.requestId);expect((await api('/api/account-mcp/requests/'+r.id+'/approve','POST',{digest:'wrong',params:args})).status).toBe(409);expect((await api('/api/account-mcp/requests/'+r.id+'/approve','POST',{digest:r.digest,params:JSON.parse(r.params_json)})).status).toBe(200);expect((await accountRpc('velnavoq.project',{projectId:pid},g.raw)).status).toBe(200);expect((await accountRpc('velnavoq.files',{projectId:pid,path:'app.js'},g.raw)).status).toBe(403);const status:any=JSON.parse((await (await accountRpc('velnavoq.request_status',{requestId:r.id},g.raw)).json() as any).result.content[0].text);expect(status).toEqual({status:'approved',projectId:pid});expect((await api('/api/account-mcp/requests/'+r.id+'/approve','POST',{digest:r.digest,params:JSON.parse(r.params_json)})).status).toBe(409);const t:any=await db.prepare('SELECT id FROM account_mcp_tokens WHERE token_hash=?').bind(await digest(g.raw!)).first();await api('/api/account-mcp/tokens/'+t.id+'/revoke','POST',{});expect((await accountRpc('velnavoq.project',{projectId:pid},g.raw)).status).toBe(401);});
it('Part33 creates only after exact approval, denial/expiry/cross-token cannot grant',async()=>{const ws:any=await db.prepare('SELECT workspace_id FROM projects WHERE id=?').bind(pid).first();const g=await accountGrant([],[],['project.read','projects.create'],true);const args={workspaceId:ws.workspace_id,name:'Owner-approved Part33',scopes:['project.read']};const req:any=JSON.parse((await (await accountRpc('velnavoq.request_create_project',args,g.raw)).json() as any).result.content[0].text);expect(await db.prepare('SELECT id FROM projects WHERE name=?').bind(args.name).first()).toBeNull();const other=await accountGrant([],[],['project.read'],true);expect((await accountRpc('velnavoq.request_status',{requestId:req.requestId},other.raw)).status).toBe(404);const r:any=await db.prepare('SELECT * FROM account_mcp_requests WHERE id=?').bind(req.requestId).first();expect((await api('/api/account-mcp/requests/'+r.id+'/approve','POST',{digest:r.digest,params:JSON.parse(r.params_json)})).status).toBe(200);const saved:any=await db.prepare('SELECT id FROM projects WHERE name=?').bind(args.name).first();expect(saved.id).toBeTruthy();expect((await accountRpc('velnavoq.project',{projectId:saved.id},g.raw)).status).toBe(200);expect(await db.prepare('SELECT * FROM mcp_sandbox_grants WHERE project_id=?').bind(saved.id).first()).toBeNull();expect((await api('/api/account-mcp/requests/'+r.id+'/approve','POST',{digest:r.digest,params:JSON.parse(r.params_json)})).status).toBe(409);expect((await db.prepare('SELECT count(*) n FROM projects WHERE name=?').bind(args.name).first<any>())?.n).toBe(1);const denied:any=JSON.parse((await (await accountRpc('velnavoq.request_project_access',{projectId:pid2,scopes:['project.read']},g.raw)).json() as any).result.content[0].text);const d:any=await db.prepare('SELECT * FROM account_mcp_requests WHERE id=?').bind(denied.requestId).first();await api('/api/account-mcp/requests/'+d.id+'/deny','POST',{digest:d.digest,params:JSON.parse(d.params_json)});expect((await api('/api/account-mcp/requests/'+d.id+'/approve','POST',{digest:d.digest,params:JSON.parse(d.params_json)})).status).toBe(409);expect((await accountRpc('velnavoq.request_project_access',{projectId:pid2,scopes:['sandbox.write']},g.raw)).status).toBe(400);});
it('Part33 request authority is opt-in; foreign targets, expired request, owner loss and replay fail closed',async()=>{const legacy=await accountGrant([]);expect((await accountRpc('velnavoq.list_access_targets',{},legacy.raw)).status).toBe(403);const g=await accountGrant([],[],['project.read'],true);const foreign:any=await db.prepare("SELECT p.id FROM projects p WHERE NOT EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=p.workspace_id AND m.user_id=?) LIMIT 1").bind(user).first();expect(foreign?.id).toBeTruthy();expect((await accountRpc('velnavoq.request_project_access',{projectId:foreign.id,scopes:['project.read']},g.raw)).status).toBe(404);const t:any=await db.prepare('SELECT id FROM account_mcp_tokens WHERE token_hash=?').bind(await digest(g.raw!)).first();const expired=crypto.randomUUID(),params={projectId:pid,scopes:['project.read']};await db.prepare('INSERT INTO account_mcp_requests(id,token_id,kind,params_json,digest,created_at,expires_at) VALUES(?,?,?,?,?,?,?)').bind(expired,t.id,'access',JSON.stringify(params),await digest(JSON.stringify(params)),Date.now()-2000,Date.now()-1).run();expect(JSON.parse((await (await accountRpc('velnavoq.request_status',{requestId:expired},g.raw)).json() as any).result.content[0].text).status).toBe('expired');expect((await api('/api/account-mcp/requests/'+expired+'/approve','POST',{digest:await digest(JSON.stringify(params)),params})).status).toBe(409);const r:any=JSON.parse((await (await accountRpc('velnavoq.request_project_access',params,g.raw)).json() as any).result.content[0].text);const row:any=await db.prepare('SELECT * FROM account_mcp_requests WHERE id=?').bind(r.requestId).first();const ws:any=await db.prepare('SELECT workspace_id FROM projects WHERE id=?').bind(pid).first();await db.prepare("UPDATE memberships SET role='editor' WHERE workspace_id=? AND user_id=?").bind(ws.workspace_id,user).run();expect((await api('/api/account-mcp/requests/'+row.id+'/approve','POST',{digest:row.digest,params:JSON.parse(row.params_json)})).status).toBe(404);await db.prepare("UPDATE memberships SET role='owner' WHERE workspace_id=? AND user_id=?").bind(ws.workspace_id,user).run();const body={digest:row.digest,params:JSON.parse(row.params_json)};const replies=await Promise.all([api('/api/account-mcp/requests/'+row.id+'/approve','POST',body),api('/api/account-mcp/requests/'+row.id+'/approve','POST',body)]);expect(replies.filter(x=>x.status===200)).toHaveLength(1);expect((await db.prepare('SELECT count(*) n FROM account_mcp_projects WHERE token_id=? AND project_id=?').bind(t.id,pid).first<any>())?.n).toBe(1);expect((await api('/api/account-mcp/requests/'+row.id+'/approve','POST',body)).status).toBe(409);});
it('Grok transport: protected account initialization challenges before success; standard no-header default supports discover/list/initialized',async()=>{const send=(body:any,raw?:string,extra:any={})=>mf.dispatchFetch(origin+'/mcp',{method:'POST',headers:{'content-type':'application/json',accept:'application/json, text/event-stream',...(raw?{authorization:'Bearer '+raw}:{}),...extra},body:JSON.stringify(body)});const init={jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'Reference standard client',version:'1'}}};const noAuth=await send(init);expect(noAuth.status).toBe(401);expect(noAuth.headers.get('www-authenticate')).toContain('/.well-known/oauth-protected-resource/mcp');expect((await send({jsonrpc:'2.0',id:8,method:'ping',params:{}})).status).toBe(401);expect((await mf.dispatchFetch(origin+'/mcp',{method:'POST',body:'invalid json'})).status).toBe(401);const g=await accountGrant([],[],['project.read','projects.create'],true);expect((await send(init,g.raw)).status).toBe(200);expect((await send({jsonrpc:'2.0',method:'notifications/initialized',params:{}},g.raw)).status).toBe(202);const listed:any=await (await send({jsonrpc:'2.0',id:2,method:'tools/list',params:{}},g.raw)).json();expect(listed.result.tools.some((t:any)=>t.name==='velnavoq.request_create_project')).toBe(true);expect((await send({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:'velnavoq.list_access_targets',arguments:{}}},g.raw)).status).toBe(200);expect((await send({jsonrpc:'2.0',id:4,method:'tools/list',params:{}},g.raw,{'MCP-Protocol-Version':'nonsense'})).status).toBe(400);expect((await send({jsonrpc:'2.0',method:'notifications/initialized',params:{}})).status).toBe(401);});
it('Part35 unsigned authorize redirects to real signin with exact resume; public metadata/CORS never enters UI auth',async()=>{const registered:any=await (await mf.dispatchFetch(origin+'/oauth/account/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({client_name:'Public test',redirect_uris:['https://client.example/callback']})})).json();const challenge=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const query=new URLSearchParams({client_id:registered.client_id,redirect_uri:'https://client.example/callback',resource:origin+'/mcp',response_type:'code',scope:'project.read',state:'opaque state&value',code_challenge:challenge,code_challenge_method:'S256'});const r=await mf.dispatchFetch(origin+'/oauth/account/authorize?'+query,{redirect:'manual'});expect(r.status).toBe(303);const login=new URL(r.headers.get('location')!);expect(login.hash.startsWith('#signin?oauthResume=')).toBe(true);const resume=new URLSearchParams(login.hash.split('?')[1]).get('oauthResume');expect(resume).toBe('/oauth/account/authorize?'+query);const resumed=await mf.dispatchFetch(origin+resume,{headers:{cookie},redirect:'manual'});expect(resumed.status).toBe(303);expect(resumed.headers.get('location')).toContain('#mcp?accountConsent=');for(const path of ['/.well-known/oauth-protected-resource','/.well-known/oauth-protected-resource/mcp','/.well-known/oauth-authorization-server','/.well-known/oauth-authorization-server/mcp','/.well-known/oauth-authorization-server/oauth/account']){const metadata=await mf.dispatchFetch(origin+path);expect(metadata.status).toBe(200);expect(metadata.headers.get('access-control-allow-origin')).toBe('*')}for(const path of ['/.well-known/openid-configuration','/.well-known/openid-configuration/oauth/account','/.well-known/unknown'])expect((await mf.dispatchFetch(origin+path)).status).toBe(404);for(const path of ['/mcp','/.well-known/oauth-protected-resource','/oauth/account/register','/oauth/account/token']){const preflight=await mf.dispatchFetch(origin+path,{method:'OPTIONS',headers:{origin:'https://grok.com','access-control-request-method':'POST','access-control-request-headers':'authorization,content-type'}});expect(preflight.status).toBe(204);expect(preflight.headers.get('access-control-allow-origin')).toBe('*');expect(preflight.headers.get('access-control-allow-credentials')).toBeNull()}const denied=await mf.dispatchFetch(origin+'/mcp',{method:'POST',headers:{origin:'https://grok.com'}});expect(denied.status).toBe(401);expect(denied.headers.get('access-control-expose-headers')).toContain('WWW-Authenticate');const ui=await mf.dispatchFetch(origin+'/api/me',{headers:{origin:'https://grok.com'}});expect(ui.headers.get('access-control-allow-origin')).toBeNull();});
it('Part36 Grok-like tolerant registration stores multiple safe redirects, exact chosen callback and PKCE, omitted scope/resource reviewed',async()=>{const register=(b:any)=>mf.dispatchFetch(origin+'/oauth/account/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});const response=await register({redirect_uris:['https://first.example/callback','https://second.example/callback'],grant_types:['authorization_code','refresh_token'],response_types:['code'],token_endpoint_auth_method:'client_secret_post',scope:'project.read unknown-extension',client_uri:'https://client.example',logo_uri:'https://client.example/logo',contacts:['private@example.test'],software_id:'private-software-id',custom_extension:{ignored:true}});expect(response.status).toBe(201);const c:any=await response.json();expect(c.client_name).toBe('AI connector');expect(c.grant_types).toEqual(['authorization_code']);expect(c.token_endpoint_auth_method).toBe('none');expect(c.redirect_uris).toHaveLength(2);const challenge=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const q=new URLSearchParams({client_id:c.client_id,redirect_uri:c.redirect_uris[1],response_type:'code',state:'multi-state',code_challenge:challenge,code_challenge_method:'S256'});const bad=new URLSearchParams(q);bad.set('redirect_uri','https://second.example/callback?different');expect((await mf.dispatchFetch(origin+'/oauth/account/authorize?'+bad,{headers:{cookie},redirect:'manual'})).status).toBe(400);const auth=await mf.dispatchFetch(origin+'/oauth/account/authorize?'+q,{headers:{cookie},redirect:'manual'});expect(auth.status).toBe(303);const id=new URL(auth.headers.get('location')!).hash.split('accountConsent=')[1];const listing:any=await (await api('/api/account-mcp')).json();const consent=listing.consents.find((s:any)=>s.id===id);expect(consent.redirect_uri).toBe(c.redirect_uris[1]);const scopes=JSON.parse(consent.scopes);expect(scopes).toContain('projects.create');expect(scopes).not.toContain('unknown-extension');const approve=await api('/api/account-mcp/consents/'+id+'/approve','POST',{clientId:c.client_id,redirectUri:c.redirect_uris[1],resource:origin+'/mcp',scopes,projectIds:[],createWorkspaceIds:[],requestApprovals:true});expect(approve.status).toBe(200);const callback=new URL((await approve.json() as any).redirect);expect(callback.origin).toBe('https://second.example');const data={grant_type:'authorization_code',client_id:c.client_id,redirect_uri:c.redirect_uris[1],code_verifier:verifier,code:callback.searchParams.get('code')!};expect((await form('/oauth/account/token',{...data,redirect_uri:c.redirect_uris[0]})).status).toBe(400);expect((await form('/oauth/account/token',{...data,code_verifier:'b'.repeat(43)})).status).toBe(400);expect((await form('/oauth/account/token',data)).status).toBe(200);for(const redirects of [[],['https://bad.example/#fragment'],['http://bad.example/callback'],['https://good.example','https://good.example']]){const denied=await register({redirect_uris:redirects});expect(denied.status).toBe(400);expect((await denied.json() as any).error).toBe('invalid_redirect_uri')}expect((await register({redirect_uris:['http://127.0.0.1:9876/callback']})).status).toBe(201);const unknown=new URLSearchParams(q);unknown.set('scope','unadvertised.scope');expect((await (await mf.dispatchFetch(origin+'/oauth/account/authorize?'+unknown,{headers:{cookie}})).json() as any).error).toBe('invalid_scope');});
it('Part38 owner approval inbox auto-summary isolated, long session renewal rotates/revokes with no CSRF bypass',async()=>{const inbox:any=await (await api('/api/approval-inbox')).json();expect(Array.isArray(inbox.items)).toBe(true);const foreign:any=await db.prepare("SELECT p.id FROM projects p WHERE NOT EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=p.workspace_id AND m.user_id=?) LIMIT 1").bind(user).first();expect(inbox.items.some((x:any)=>x.project_id===foreign.id)).toBe(false);const oldHash=await digest(cookie.split('=')[1]!);await db.prepare('UPDATE sessions SET created_at=?,last_seen_at=? WHERE token_hash=?').bind(Math.floor(Date.now()/1000)-90000,Math.floor(Date.now()/1000)-7200,oldHash).run();expect((await api('/api/me')).status).toBe(200);const renewed=await api('/api/auth/renew','POST',{});expect(renewed.status).toBe(200);expect(renewed.headers.get('set-cookie')).toContain('Max-Age=2592000');expect(renewed.headers.get('set-cookie')).toContain('SameSite=Lax');const newCookie=renewed.headers.get('set-cookie')!.split(';')[0]!;expect(newCookie).not.toBe(cookie);expect((await api('/api/me')).status).toBe(200);const rawOld=cookie;cookie=newCookie;expect((await api('/api/auth/logout','POST',{})).status).toBe(200);expect((await api('/api/me')).status).toBe(401);cookie=rawOld;expect((await api('/api/me')).status).toBe(401);const login=await api('/api/auth/login','POST',{email:'mcp-owner@example.test',password:'secure-password-long-1234'});cookie=login.headers.get('set-cookie')!.split(';')[0]!;csrf=(await login.json() as any).csrfToken;});
